  /* ============================================================
     ENGINE:  randomization, blueprint sampling, scoring
     ============================================================ */
  function shuffle(arr) {
    var a = arr.slice();
    for (var i = a.length - 1; i > 0; i--) {
      var j = Math.floor(Math.random() * (i + 1));
      var t = a[i]; a[i] = a[j]; a[j] = t;
    }
    return a;
  }

  // Build a mock exam that covers every topic, then fills to `count`.
  function buildExam(subject, count) {
    var pool = POOLS[subject];
    var total = count && count > 0 ? Math.min(count, pool.length) : pool.length;

    // group by topic
    var byTopic = {};
    pool.forEach(function (q) { (byTopic[q.topic] = byTopic[q.topic] || []).push(q); });
    var topics = Object.keys(byTopic);

    var picked = [];
    var usedIds = {};

    // 1) at least one from each topic (round-robin) so nothing disappears
    var shuffledByTopic = {};
    topics.forEach(function (t) { shuffledByTopic[t] = shuffle(byTopic[t]); });
    var round = 0, added = true;
    while (picked.length < total && added) {
      added = false;
      for (var i = 0; i < topics.length && picked.length < total; i++) {
        var list = shuffledByTopic[topics[i]];
        if (list[round]) {
          var q = list[round];
          if (!usedIds[q.id]) { usedIds[q.id] = 1; picked.push(q); added = true; }
        }
      }
      round++;
    }

    // 2) shuffle order, then prepare display (shuffle MC choices)
    var exam = shuffle(picked).slice(0, total).map(function (q) {
      var display;
      if (q.type === "tf") {
        display = { choices: q.choices.slice(), correct: q.answer };
      } else {
        var idx = q.choices.map(function (_, i) { return i; });
        var order = shuffle(idx);
        display = {
          choices: order.map(function (i) { return q.choices[i]; }),
          correct: order.indexOf(q.answer)
        };
      }
      return {
        ref: q, id: q.id, topic: q.topic, difficulty: q.difficulty, type: q.type,
        question: q.question, explanation: q.explanation, image: q.img, read: q.read,
        choices: display.choices, correct: display.correct
      };
    });
    return exam;
  }

  function grade(exam, answers) {
    var correct = 0, wrong = 0, wrongTopics = {};
    exam.forEach(function (item, i) {
      var a = answers[i];
      if (a === item.correct) correct++;
      else {
        wrong++;
        wrongTopics[item.topic] = (wrongTopics[item.topic] || 0) + 1;
      }
    });
    var total = exam.length;
    return {
      correct: correct, wrong: wrong, total: total,
      percentage: total ? Math.round((correct / total) * 100) : 0,
      wrongTopics: wrongTopics
    };
  }

  function levelFor(pct) {
    if (pct >= 90) return { emoji: "🌟", title: "ยอดเยี่ยม!", msg: "เก่งมากเลย เพอร์เฟกต์สุด ๆ", cls: "lv-star" };
    if (pct >= 70) return { emoji: "😊", title: "ดีมาก!", msg: "ทำได้ดีมาก อีกนิดเดียวก็เต็ม", cls: "lv-good" };
    if (pct >= 50) return { emoji: "👍", title: "พยายามอีกนิด", msg: "มาถูกทางแล้ว ลองทบทวนอีกหน่อยนะ", cls: "lv-ok" };
    return { emoji: "💪", title: "ลองทบทวนอีกครั้งนะ", msg: "ไม่เป็นไรเลย ทบทวนแล้วลองใหม่ เก่งขึ้นแน่นอน", cls: "lv-try" };
  }

  /* ---------- LocalStorage (exam history) ---------- */
  var LS_KEY = "p3exam_history_v1";
  function loadHistory() {
    try { return JSON.parse(localStorage.getItem(LS_KEY)) || []; }
    catch (e) { return []; }
  }
  function saveResult(rec) {
    var h = loadHistory();
    h.unshift(rec);
    if (h.length > 60) h = h.slice(0, 60);
    try { localStorage.setItem(LS_KEY, JSON.stringify(h)); } catch (e) {}
  }
  function lastResultFor(subject) {
    var h = loadHistory();
    for (var i = 0; i < h.length; i++) if (h[i].subject === subject) return h[i];
    return null;
  }
  function fmtDate(iso) {
    try {
      var d = new Date(iso);
      var months = ["ม.ค.", "ก.พ.", "มี.ค.", "เม.ย.", "พ.ค.", "มิ.ย.", "ก.ค.", "ส.ค.", "ก.ย.", "ต.ค.", "พ.ย.", "ธ.ค."];
      return d.getDate() + " " + months[d.getMonth()] + " " + (d.getFullYear() + 543 - 2500 < 100 ? (d.getFullYear() + 543) : (d.getFullYear() + 543)) +
        " " + ("0" + d.getHours()).slice(-2) + ":" + ("0" + d.getMinutes()).slice(-2);
    } catch (e) { return ""; }
  }

